        `Invalid threshold format: '${str}'. Expected: metric=min (e.g., exact_match=0.8)`
      );
      process.exit(2);
    }

    const [metric, valueStr] = parts;
    const min = parseFloat(valueStr);

    if (isNaN(min) || min < 0 || min > 1) {
      log.error(
        `Invalid threshold value: '${valueStr}'. Must be a number between 0 and 1`
      );
      process.exit(2);
    }

    return { metric: metric.trim(), min };
  });
}
```

**Update runEvalCommand:**
```typescript
function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);

  // NEW: Parse and validate thresholds
  let parsedThresholds: ParsedThreshold[] = [];
  if (options.threshold && options.threshold.length > 0) {
    parsedThresholds = parseThresholds(options.threshold);
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });

  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  // NEW: Pass thresholds to generateReport
  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: parsedThresholds
  });

  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });

  log.success('Evaluation report generated.', { path: resolvedPath });

  // NEW: Check threshold results and exit accordingly
  if (parsedThresholds.length > 0 && !report.metadata.passed) {
    log.error('Evaluation thresholds not met');
    process.exit(1);
  }
}
```

### Phase 3: Markdown Reporter Update

**Update toMarkdown in reporters.js:**
```javascript
export function toMarkdown(report) {
  const lines = [];
  lines.push('# FRAI Evaluation Report');
  lines.push('');
  lines.push(`- **Generated At:** ${report.metadata.generatedAt}`);
  lines.push(`- **Outputs File:** ${report.metadata.outputsPath}`);
  if (report.metadata.referencesPath) {
    lines.push(`- **References File:** ${report.metadata.referencesPath}`);
  }
  lines.push(`- **Total Samples:** ${report.metadata.totalSamples}`);

  // NEW: Add thresholds section
  if (report.metadata.thresholds && report.metadata.thresholds.length > 0) {
    lines.push('');
    lines.push('## Thresholds');
    lines.push('');
    const status = report.metadata.passed ? 'PASS' : 'FAIL';
    lines.push(`- **Overall Status:** ${status}`);
    lines.push('');
    report.metadata.thresholds.forEach(t => {
      const tStatus = t.passed ? 'PASS' : 'FAIL';
      const scoreDisplay = t.score !== null ? t.score.toFixed(4) : 'n/a';
      lines.push(`- **${t.metric}:** ${tStatus} (minimum: ${t.min}, actual: ${scoreDisplay})`);
    });
  }

  lines.push('');
  lines.push('## Metrics');
  lines.push('');
  report.metrics.forEach((metric) => {
    lines.push(`### ${metric.label}`);
    lines.push('');
    lines.push(`- **Score:** ${metric.score ?? 'n/a'}`);
    if (typeof metric.total === 'number') {
      lines.push(`- **Total Samples:** ${metric.total}`);
    }
    if (typeof metric.matches === 'number') {
      lines.push(`- **Matches:** ${metric.matches}`);
    }
    if (typeof metric.flagged === 'number') {
      lines.push(`- **Flagged Samples:** ${metric.flagged}`);
    }
    if (typeof metric.averageDelta === 'number') {
      lines.push(`- **Average Delta:** ${metric.averageDelta}`);
    }
    lines.push('');
  });

  lines.push('---');
  lines.push('*Generated by FRAI Evaluation Harness*');
  return lines.join('\n');
}
```

