      );
    }
    const score = metricsMap.get(t.metric).score;
    const passed = score !== null && score >= t.min;
    return { metric: t.metric, min: t.min, score, passed };
  });
}

function calculateReportPassed(thresholdResults) {
  return thresholdResults.length === 0 || thresholdResults.every(t => t.passed);
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds = [],
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const metadata = {
    generatedAt,
    outputsPath,
    referencesPath,
    totalSamples
  };

  if (thresholds.length > 0) {
    const thresholdResults = validateThresholds(thresholds, evaluations);
    metadata.passed = calculateReportPassed(thresholdResults);
    metadata.thresholds = thresholdResults;
  }

  return {
    metadata,
    metrics: evaluations
  };
}

