486	  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
487	    evaluations,
488	    outputsPath: dataset.outputsPath,
489	    referencesPath: dataset.referencesPath
490	  });
491	  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
492	    report,
493	    format: options.format ?? 'json',
494	    reportPath: options.report
495	  });
496	  log.success('Evaluation report generated.', { path: resolvedPath });
497	}
