    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('validates thresholds correctly when all pass', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: [
        { metric: 'exact_match', min: 0.5 },
        { metric: 'toxicity', min: 0.9 }
      ]
    });

    expect(report.metadata.passed).toBe(true);
    expect(report.metadata.thresholds).toHaveLength(2);
    expect(report.metadata.thresholds[0]).toMatchObject({
      metric: 'exact_match',
      min: 0.5,
      passed: true
    });
    expect(report.metadata.thresholds[1]).toMatchObject({
      metric: 'toxicity',
      min: 0.9,
      passed: true
    });
    expect(typeof report.metadata.thresholds[0].score).toBe('number');
    expect(typeof report.metadata.thresholds[1].score).toBe('number');
  });

  it('fails report when any threshold does not pass', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: [
        { metric: 'exact_match', min: 0.99 }
      ]
    });

    expect(report.metadata.passed).toBe(false);
    expect(report.metadata.thresholds[0].passed).toBe(false);
  });

  it('throws error for unknown metric', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    expect(() => {
      generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        thresholds: [{ metric: 'unknown_metric', min: 0.8 }]
      });
    }).toThrow('Unknown metric: \'unknown_metric\'');
  });

  it('includes available metrics in unknown metric error', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    try {
      generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        thresholds: [{ metric: 'bad_metric', min: 0.8 }]
      });
    } catch (error) {
      expect(error.message).toContain('exact_match');
      expect(error.message).toContain('toxicity');
      expect(error.message).toContain('length_variance');
    }
  });

  it('fails threshold when metric has null score', () => {
    const evaluations = [
      { id: 'exact_match', label: 'Exact Match', score: null, total: 0 }
    ];

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      thresholds: [{ metric: 'exact_match', min: 0.5 }]
    });

    expect(report.metadata.passed).toBe(false);
    expect(report.metadata.thresholds[0]).toMatchObject({
      metric: 'exact_match',
      score: null,
      passed: false
    });
  });

